onSeeking() {
  this.#throttledTriggerTranslations.cancel(); // 暂停预翻译，防止产生大量断续的无效预翻译网络请求
  // 强制高亮展示对应处的字幕，且不在此触发翻译
  this.#syncToCurrentTime({ forceRender: true, triggerTranslations: false });
}

/**
 * 进度条拖动完毕，落定后触发
 */
onSeek() {
  this.#throttledTriggerTranslations.cancel();
  this.#syncToCurrentTime({ forceRender: true });
  this.#scheduleSeekSettledSync(); // 调度下一帧做一次确认位置同步

// 2. 创建字幕译文 (translation) 显示节点
const p2 = document.createElement("p");
p2.style.cssText = this.#setting.translationStyle;
p2.style.margin = "0";
if (isHoverLookupEnabled) {
  p2.innerHTML = trustedTypesHelper.createHTML(
    wrapWordsWithSpans(subtitle.translation || "...")
  );
} else {
  p2.textContent = truncateWords(subtitle.translation) || "...";
}

// 3. 根据用户设置，决定显示双语对照还是仅显示翻译
if (this.#setting.isBilingual) {
  const children =
    this.#setting.displayOrder === "translation-first"
      ? [p2, p1]
      : [p1, p2];
  this.#captionWindowEl.replaceChildren(...children);
} else {
  this.#captionWindowEl.replaceChildren(p2);
}

try {
  const payloads = tasksToProcess.map((item) => item.payload);
  const batchArgs = tasksToProcess[0].args;

  // 调用具体的翻译函数（可能返回 AsyncGenerator 或 Promise）
  const generator = taskFn(payloads, batchArgs);

  // 检查是否是异步生成器（用于流式逐句返回结果的翻译源，如 OpenAI/Gemini）
  if (generator && typeof generator[Symbol.asyncIterator] === "function") {
    for await (const item of generator) {
      const id = item.id;
      const isComplete = item.isComplete !== false; // 默认完成状态为 true
      const taskItem = tasksToProcess[id];

      if (taskItem) {
        // 流式渲染的中间状态回调（当 isComplete 为 false 且有分块回调时）
        if (!isComplete && taskItem.args?.onStreamChunk) {
          taskItem.args.onStreamChunk({
            id,
            text: item.partialText,
            isComplete: false,
          });
        }
        // 单个段落完全翻译结束：触发回调并 resolve 对应任务的 Promise
        if (isComplete) {
          if (taskItem.args?.onStreamChunk) {
            taskItem.args.onStreamChunk({
              id,
              text: item.result,
              isComplete: true,
            });
          }
          if (!taskItem.resolved) {
            taskItem.resolved = true;
            taskItem.resolve(item.result);
          }
        }
      }

function getPromptCacheFields(apiSetting = {}, promptScope, glossary = {}) {
  let fields = [];

  if (promptScope === PROMPT_CACHE_SCOPE_BATCH) {
    fields = [apiSetting.systemPrompt || ""];
  } else if (promptScope === PROMPT_CACHE_SCOPE_NOBATCH) {
    fields = [
      apiSetting.nobatchPrompt || "",
      apiSetting.nobatchUserPrompt ?? defaultNobatchUserPrompt,
    ];
  } else if (promptScope === PROMPT_CACHE_SCOPE_DICT) {
    return [
      apiSetting.dictPrompt || "",
      apiSetting.dictUserPrompt ?? defaultDictUserPrompt,
    ];
  } else if (promptScope === PROMPT_CACHE_SCOPE_QWEN_MT) {
    fields = [];
  } else {
    return [];
  }

  fields.push(apiSetting.tone || "", apiSetting.aiTerms || "");
  const glossaryEntries = Object.entries(glossary || {}).sort();
  if (glossaryEntries.length) {
    fields.push(JSON.stringify(glossaryEntries));
  }
  return fields;
}

async function getPromptCacheSig(apiSetting = {}, promptScope, glossary) {
  const promptText = [
    promptScope,
    ...getPromptCacheFields(apiSetting, promptScope, glossary),
  ].join("\n");

  return (await getCacheDigest(promptText, PROMPT_CACHE_SALT)).slice(0, 16);

destroy() {
  logger.info("Bilingual Subtitle Manager: Destroying...");
  this.#translationSessionId += 1; // 递增会话 ID，使当前在途的异步请求回调全部失效
  this.#abortController?.abort(); // 中止未返回的底层请求
  this.#abortController = null;
  this.onSubtitleUpdate = null;
  this.#removeEventListeners(); // 解绑视频播放监听
  this.#throttledTriggerTranslations?.cancel(); // 取消节流触发器
  if (this.#seekSyncRafId !== null) {
    cancelAnimationFrame(this.#seekSyncRafId);
    this.#seekSyncRafId = null;
  }
  // 移除字幕渲染容器
  this.#captionWindowEl?.parentElement?.parentElement?.remove();
  // 释放 MutationObserver 监听器
  this.#playerControlBarObserver?.disconnect();
  this.#playerControlBarObserver = null;
  this.#playerResizeObserver?.disconnect();
  this.#playerResizeObserver = null;
  this.#syncPaperBottomAfterDrag = null;
  this.#syncPaperPosition = null;
  this.#formattedSubtitles = [];
  this.#wordTooltipController?.destroy();
